from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bucket_end = None
        self._minute_bucket = []

        self._current_slice = None
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._held_expiry = None
        self._entry_price = None
        self._no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self._expiration_guard
        )

    def OnData(self, slice):
        self._current_slice = slice

        self._handle_unexpected_spy_position()
        self._handle_expiration_guard()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar)

        self._evaluate_option_exit()

    def _update_five_minute_bar(self, minute_bar):
        local_end = self.Time.replace(second=0, microsecond=0)

        if local_end.time() <= time(9, 30) or local_end.time() > time(16, 0):
            return

        minutes_to_boundary = (5 - local_end.minute % 5) % 5
        bucket_end = local_end + timedelta(minutes=minutes_to_boundary)

        if self._minute_bucket_end != bucket_end:
            if self._minute_bucket_end is not None:
                self._finalize_bucket()

            self._minute_bucket_end = bucket_end
            self._minute_bucket = []

        self._minute_bucket.append((local_end, minute_bar))

        if local_end == bucket_end:
            self._finalize_bucket()

    def _finalize_bucket(self):
        bucket_end = self._minute_bucket_end
        bars = self._minute_bucket

        self._minute_bucket_end = None
        self._minute_bucket = []

        if bucket_end is None or len(bars) != 5:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        actual_times = [item[0] for item in bars]
        if actual_times != expected_times:
            return

        close = bars[-1][1].Close

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        point = IndicatorDataPoint(bucket_end, close)
        self.fast.Update(point)
        self.slow.Update(point)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        self._try_enter_call()

    def _try_enter_call(self):
        current_date = self.Time.date()

        if self._no_entry_date == current_date:
            return

        if self._entry_order_open():
            return

        if self._held_symbol is not None:
            if self.Portfolio[self._held_symbol].Quantity != 0:
                return

        spy_bar = self._current_slice.Bars.get(self.spy)
        if spy_bar is None:
            self.Debug("Skipped call selection: no current SPY bar.")
            return

        spy_price = spy_bar.Close
        chain = self._current_slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Call entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_option_exit(self):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self.Portfolio[self._held_symbol].Quantity <= 0:
            return

        if self._exit_order_open():
            return

        current_date = self.Time.date()

        if (
            self._held_expiry is not None
            and current_date == self._previous_trading_day(self._held_expiry)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration-preceding-day time stop")
            return

        quote = self._current_slice.QuoteBars.get(self._held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None and self._exit_order_open():
            self._exit_ticket.Cancel("Replacing open exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Option exit submitted: {0}; reason: {1}".format(
                self._held_symbol,
                reason
            )
        )

    def _expiration_guard(self):
        self._handle_expiration_guard()

    def _handle_expiration_guard(self):
        if self._held_symbol is None or self._held_expiry is None:
            return

        if self.Time.date() >= self._held_expiry:
            self._no_entry_date = self.Time.date()

            if self.Portfolio[self._held_symbol].Quantity > 0:
                self._submit_exit("Expiration processing guard")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        self._no_entry_date = self.Time.date()

        self.Debug(
            "Unexpected SPY exercise or assignment position detected; "
            "liquidating {0} shares.".format(quantity)
        )

        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._held_expiry = self.Securities[
                    self._held_symbol
                ].Symbol.ID.Date.date()

                self.Debug(
                    "Call entry filled: {0}, price {1}".format(
                        self._held_symbol,
                        self._entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Call exit filled: {0}, price {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

                self._exit_ticket = None
                self._entry_ticket = None
                self._held_symbol = None
                self._held_expiry = None
                self._entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None
