from datetime import datetime, timedelta, time


class SpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(0), timedelta(days=1095))
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_last_close = None

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiry_date = None
        self.time_stop_date = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()
        self._evaluate_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._consume_minute_bar(bar, slice)

    def _consume_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_time = bar.Time
        if minute_time.tzinfo is not None:
            minute_time = minute_time.replace(tzinfo=None)

        current_time = minute_time.time()
        if current_time < time(9, 30) or current_time >= time(16, 0):
            return

        bucket_minute = (minute_time.minute // 5) * 5
        bucket_start = datetime(
            minute_time.year,
            minute_time.month,
            minute_time.day,
            minute_time.hour,
            bucket_minute
        )

        if self.bucket_start != bucket_start:
            if self.bucket_start is not None and self.bucket_count == 5:
                self._process_five_minute_bar(
                    self.bucket_start + timedelta(minutes=5),
                    self.bucket_last_close,
                    slice
                )

            self.bucket_start = bucket_start
            self.bucket_count = 0
            self.bucket_valid = True
            self.bucket_last_close = None

        expected_time = self.bucket_start + timedelta(minutes=self.bucket_count)

        if minute_time != expected_time:
            self.bucket_valid = False

        self.bucket_count += 1
        self.bucket_last_close = bar.Close

        if self.bucket_count == 5:
            if self.bucket_valid:
                self._process_five_minute_bar(
                    self.bucket_start + timedelta(minutes=5),
                    self.bucket_last_close,
                    slice
                )

            self.bucket_start = None
            self.bucket_count = 0
            self.bucket_valid = True
            self.bucket_last_close = None

    def _process_five_minute_bar(self, bar_end_time: datetime,
                                 close: float, slice: Slice):
        previous_fast = None
        previous_slow = None

        if len(self.fast_closes) == 5:
            previous_fast = sum(self.fast_closes) / 5.0

        if len(self.slow_closes) == 20:
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        eligible_time = time(9, 45) <= bar_end_time.time() <= time(14, 30)

        bullish_cross = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            self.Debug("Skipped call selection: no current SPY price.")
            return

        spy_price = spy_bar.Close
        chain = self._get_option_chain(slice)

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

