class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(timedelta(0), timedelta(days=730))
        )

        self.closes = deque(maxlen=20)
        self.current_bucket = None
        self.current_bucket_close = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(9, 30),
            self._expiration_processing
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(15, 45),
            self._scheduled_time_stop
        )

    def OnData(self, slice: Slice):
        self._liquidate_unexpected_spy_position()

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar, slice)

        self._evaluate_profit_target(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = self.Time
        if local_time.date() != bar.EndTime.date():
            local_time = self.Time

        t = local_time.time()
        if t < datetime.time(9, 30) or t > datetime.time(16, 0):
            return

        minutes = t.hour * 60 + t.minute
        bucket_start_minutes = (minutes // 5) * 5
        bucket = (local_time.date(), bucket_start_minutes)

        if self.current_bucket is None:
            self.current_bucket = bucket
            self.current_bucket_close = bar.Close
            return

        if bucket != self.current_bucket:
            completed_date, completed_start = self.current_bucket
            completed_end_minutes = completed_start + 5
            completed_end = datetime.datetime.combine(
                completed_date,
                datetime.time(
                    completed_end_minutes // 60,
                    completed_end_minutes % 60
                )
            )

            self._process_completed_five_minute_bar(
                completed_end,
                self.current_bucket_close,
                slice
            )

            self.current_bucket = bucket
            self.current_bucket_close = bar.Close
        else:
            self.current_bucket_close = bar.Close

    def _process_completed_five_minute_bar(
        self,
        bar_end: datetime.datetime,
        close: float,
        slice: Slice
    ):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_time = bar_end.time()
        eligible_time = (
            datetime.time(9, 45) <= end_time <= datetime.time(14, 30)
        )

        if bullish_crossover and eligible_time:
            self._attempt_entry(slice, close)

    def _attempt_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self._has_option_holding() or self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible_expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= today + timedelta(days=7)
            }
        )

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = eligible_expirations[0]

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if not self._has_option_holding():
            return

        if self.entry_price is None:
            return

        quote = slice.QuoteBars.get(self.entry_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _scheduled_time_stop(self):
        if not self._has_option_holding():
            return

        expiry = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        if self.Time.date() == expiry - timedelta(days=1):
            self._submit_exit("expiration time stop")

    def _expiration_processing(self):
        today = self.Time.date()

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")
            self.entry_ticket = None
            self.entry_symbol = None

        self.no_entry_date = today

        if self._has_option_holding():
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        self.exit_ticket = self.MarketOrder(self.entry_symbol, -quantity)
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        message = (order_event.Message or "").lower()
        assignment = bool(getattr(order_event, "IsAssignment", False))
        exercise_or_assignment = (
            assignment
            or "exercise" in message
            or "assignment" in message
        )

        if exercise_or_assignment:
            self.Debug("Unexpected exercise or assignment detected.")
            self.no_entry_date = self.Time.date()
            self._liquidate_unexpected_spy_position()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.entry_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Option exit filled.")
            self.exit_ticket = None
            self.entry_ticket = None
            self.entry_symbol = None
            self.entry_price = None

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.Debug("Liquidating unexpected SPY equity position.")
            self.MarketOrder(self.spy_symbol, -quantity)
            self.no_entry_date = self.Time.date()

    def _has_option_holding(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Quantity > 0
        )

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        )

